# 1. repr(DEFAULT) is '<DEFAULT>'
# 2. bool(DEFAULT) is False
# 3. Type-hinting example: function accepting list[str] | None | type[DEFAULT]
def spam(ham: list[str] | None | type[DEFAULT] = DEFAULT):
    if ham is DEFAULT:
        ham = ['prosciutto', 'jamon']
    if ham is None:
        return 'Eggs?'
    else:
        return f'{len(ham)} ham(s).'

